CREATE SET TABLE MDP01_META.META_ETL_JOB_STEP_TEMPLATE ,FALLBACK ,     NO BEFORE JOURNAL,     NO AFTER JOURNAL,     CHECKSUM = DEFAULT,     DEFAULT MERGEBLOCKRATIO,     MAP = TD_MAP1     (      STEP_TEMPLATE_ID INTEGER NOT NULL GENERATED ALWAYS AS IDENTITY           (START WITH 1             INCREMENT BY 1             MINVALUE -2147483647             MAXVALUE 2147483647             NO CYCLE),      TEMPLATE_ID INTEGER,      STEP_NAME VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      STEP_CODE VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC,      STEP_ORDER INTEGER NOT NULL DEFAULT 10 ,      STEP_CATEGORY VARCHAR(50) CHARACTER SET LATIN NOT CASESPECIFIC NOT NULL,      SQL_TEMPLATE_PATH VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      SQL_INLINE CLOB(16777216) CHARACTER SET UNICODE,      PYTHON_MODULE VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC,      PYTHON_FUNCTION VARCHAR(100) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_PARAMETERS CLOB(16777216) CHARACTER SET UNICODE,      REQUIRED_PARAMETERS VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      OPTIONAL_PARAMETERS VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_CONDITION_SQL VARCHAR(1000) CHARACTER SET LATIN NOT CASESPECIFIC,      DEFAULT_SKIP_ON_EMPTY CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC CHECK ( DEFAULT_SKIP_ON_EMPTY  IN ('Y','N') ) DEFAULT 'N',      DEFAULT_IS_CRITICAL CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC CHECK ( DEFAULT_IS_CRITICAL  IN ('Y','N') ) DEFAULT 'Y',      DEFAULT_ROLLBACK_ON_ERROR CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC CHECK ( DEFAULT_ROLLBACK_ON_ERROR  IN ('Y','N') ) DEFAULT 'Y',      TAGS VARCHAR(500) CHARACTER SET LATIN NOT CASESPECIFIC,      BESCHREIBUNG VARCHAR(2000) CHARACTER SET LATIN NOT CASESPECIFIC,      USAGE_NOTES VARCHAR(4000) CHARACTER SET LATIN NOT CASESPECIFIC,      IS_ACTIVE CHAR(1) CHARACTER SET LATIN NOT CASESPECIFIC CHECK ( IS_ACTIVE  IN ('Y','N') ) DEFAULT 'Y',      CREATED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      CREATE_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),      MODIFIED_BY VARCHAR(200) CHARACTER SET LATIN NOT CASESPECIFIC DEFAULT USER ,      LAST_ALTER_TIMESTAMP TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6))PRIMARY INDEX ( STEP_TEMPLATE_ID );